@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Inter:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#090b18;--panel:#111426;--line:#252a43;--muted:#858ba7;--white:#f4f4fa;--cyan:#51e6ff;--pink:#ff4d79;--gold:#ffdc6b;--font:'Inter',sans-serif;--display:'Barlow Condensed',Impact,sans-serif;--mono:'DM Mono',monospace}
*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 42% 0%,#171a32 0,#0b0d1b 42%,#080a15 100%);color:var(--white);font-family:var(--font);padding:0 24px}.app-shell{max-width:1392px;margin:0 auto}.topbar{height:74px;border-bottom:1px solid #25283b;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:#f8f8ff;font-family:var(--display);font-size:20px;font-weight:900;letter-spacing:1px}.brand-light{font-weight:600;color:#8b90aa;margin-left:4px}.brand-mark{width:29px;height:29px;display:grid;place-items:center;background:var(--cyan);color:#08101a;font-size:20px;font-style:italic;clip-path:polygon(0 0,100% 0,84% 72%,22% 100%)}.top-note{font:10px var(--mono);letter-spacing:1.6px;color:#a6abc1}.top-note i{font-style:normal;color:#4a506a;padding:0 8px}.live-dot,.status-dot{width:7px;height:7px;display:inline-block;background:#7cffbe;border-radius:50%;box-shadow:0 0 11px #65ffb4;margin-right:8px}.sound-button{background:none;border:1px solid #2a2e47;color:#cdd0e0;border-radius:5px;padding:8px 11px;font:10px var(--mono);letter-spacing:.7px;cursor:pointer}.sound-button span{margin-left:5px;color:#9298b1}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 284px;gap:25px;padding:25px 0 19px}.game-column{min-width:0}.arena-wrap{position:relative;overflow:hidden;border:1px solid #313653;background:#11152d;box-shadow:0 18px 60px #0007;border-radius:7px;aspect-ratio:16/9;min-height:320px}.arena-wrap canvas{display:block;width:100%;height:100%;object-fit:contain;image-rendering:pixelated}.game-intro{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;background:linear-gradient(180deg,#0b0d1a42 0%,#0b0d1aec 57%,#0b0d1af7 100%);padding:17px 20px;transition:opacity .3s}.game-intro.hidden{opacity:0;pointer-events:none}.intro-eyebrow,.select-label,.intro-foot,.panel-kicker,.side-footer,.page-footer,.status-line{font-family:var(--mono);letter-spacing:1.4px}.intro-eyebrow{font-size:9px;color:#aab2d1;margin-bottom:2px}.intro-eyebrow span{display:inline-block;height:1px;width:25px;vertical-align:middle;background:var(--cyan);margin:0 8px 3px 0}.game-intro h1{font:900 clamp(42px,7vw,72px)/.72 var(--display);font-style:italic;letter-spacing:1px;margin:11px 0 5px;text-shadow:4px 5px 0 #16162e}.game-intro h1 em{font-style:italic;color:var(--cyan);font-size:.77em;letter-spacing:5px}.intro-copy{font-size:11px;color:#b8bdd1;margin:7px 0 13px}.intro-copy b{color:#fff}.select-label{font-size:8px;color:#9299b5;margin-bottom:7px}.fighter-select{display:flex;gap:9px;width:min(380px,100%)}.fighter-card{position:relative;flex:1;display:flex;align-items:center;text-align:left;gap:9px;padding:7px 10px;background:#171a2fdd;border:1px solid #343953;border-radius:4px;color:#eef1fa;cursor:pointer;transition:.18s}.fighter-card:hover{border-color:#747c9c;transform:translateY(-1px)}.fighter-card.selected[data-fighter=sonic]{border-color:#50dff5;background:#162840}.fighter-card.selected[data-fighter=shadow]{border-color:#ff5578;background:#321a30}.card-sprite{width:38px;height:42px;flex:none;display:block;background-repeat:no-repeat;image-rendering:pixelated;position:relative}.sonic-sprite:before,.shadow-sprite:before{content:'';position:absolute;left:8px;top:7px;width:20px;height:25px;background:#168bdc;box-shadow:4px -5px 0 -2px #187ada,-4px -3px 0 -2px #168bdc,0 0 0 4px #f6c39c,4px 9px 0 -1px #fff,0 20px 0 -4px #f7f6ff,-7px 18px 0 -3px #f34648,8px 18px 0 -3px #ed4245}.shadow-sprite:before{background:#242536;box-shadow:4px -5px 0 -2px #272a39,-4px -3px 0 -2px #202331,0 0 0 4px #e6ad89,4px 9px 0 -1px #e52d50,0 20px 0 -4px #e9e9f2,-7px 18px 0 -3px #e7354f,8px 18px 0 -3px #ed314e}.fighter-info{display:flex;flex-direction:column;gap:3px}.fighter-info b{font:800 16px var(--display);letter-spacing:1px}.fighter-info small{font:7px var(--mono);color:#a7aec5;letter-spacing:.45px}.pick-check{display:none;position:absolute;right:7px;top:5px;font-size:12px;color:var(--cyan)}.fighter-card.selected .pick-check{display:block}.fighter-card.selected[data-fighter=shadow] .pick-check{color:var(--pink)}.play-button{display:flex;align-items:center;justify-content:center;gap:34px;width:min(380px,100%);margin-top:9px;padding:11px 16px;border:0;border-radius:3px;background:var(--cyan);color:#08111c;cursor:pointer;font:800 13px var(--display);letter-spacing:1.3px;box-shadow:0 4px 22px #45cfe833;transition:.18s}.play-button:hover{background:#a2f5ff;transform:translateY(-1px)}.play-button b{font:20px var(--font)}.intro-foot{font-size:7px;color:#777e9b;margin-top:8px}.intro-foot span{margin:0 4px}
.battle-hud{position:absolute;left:0;right:0;top:0;padding:16px 21px;display:grid;grid-template-columns:1fr 66px 1fr;gap:16px;align-items:start;opacity:0;pointer-events:none;transition:opacity .3s}.battle-hud.active{opacity:1}.fighter-hud{min-width:0}.hud-name{display:flex;align-items:center;gap:9px;margin-bottom:6px}.cpu-hud .hud-name{justify-content:flex-end;text-align:right}.hud-icon{width:29px;height:29px;border:1px solid #50dff5;background:#10273a;color:var(--cyan);display:grid;place-items:center;font:900 italic 19px var(--display);clip-path:polygon(0 0,100% 0,100% 79%,20% 100%)}.shadow-icon{border-color:#fa4b70;background:#351727;color:#ff5577;clip-path:polygon(0 0,100% 0,80% 100%,0 80%)}.hud-name span:not(.hud-icon){display:flex;flex-direction:column}.hud-name b{font:800 16px var(--display);letter-spacing:1.1px}.hud-name small{font:7px var(--mono);color:#abb1c9;letter-spacing:1px;margin-top:1px}.health-track{width:100%;height:10px;background:#36394a;border:1px solid #51556b;transform:skewX(-11deg);overflow:hidden}.health-fill{height:100%;width:100%;background:linear-gradient(90deg,#35dcfa,#a4f6ff);transition:width .18s}.cpu-hud .health-fill{margin-left:auto;background:linear-gradient(90deg,#ff7188,#ff3c62)}.meter-row{margin-top:5px;display:flex;align-items:center;gap:6px;color:#c0c4d5;font:6px var(--mono);letter-spacing:.65px}.cpu-hud .meter-row{justify-content:flex-end}.meter-track{width:75px;height:4px;background:#33364a;border-radius:5px;overflow:hidden}.meter-fill{height:100%;width:0;background:#ffe57a;transition:width .18s}.cpu-hud .meter-fill{margin-left:auto;background:#ff7390}.meter-row b{font-size:7px;color:#e5e8f4}.round-clock{text-align:center;padding-top:0}.round-clock small,.round-clock span{display:block;font:6px var(--mono);letter-spacing:1px;color:#b7bdd3}.round-clock strong{display:block;font:800 29px/.95 var(--display);color:#fff;text-shadow:0 0 16px #91eaff65;margin:3px 0}.round-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;background:#070917aa;opacity:0;pointer-events:none;transition:opacity .25s}.round-overlay.show{opacity:1;pointer-events:auto}.round-stamp{font:10px var(--mono);letter-spacing:4px;color:var(--cyan)}.round-message{font:900 clamp(47px,9vw,92px)/1 var(--display);font-style:italic;letter-spacing:2px;text-shadow:4px 5px #17162e}.round-overlay button{margin-top:18px;border:1px solid #59627c;background:#171c32;color:#f6f7ff;padding:10px 18px;font:10px var(--mono);letter-spacing:1.5px;cursor:pointer}.round-overlay button:hover{border-color:var(--cyan);color:var(--cyan)}.round-overlay button span{font-size:16px;margin-left:9px}.transform-flash{position:absolute;inset:30% 0 auto;text-align:center;color:#fff4af;font:900 clamp(34px,7vw,70px)/.84 var(--display);font-style:italic;letter-spacing:3px;text-shadow:0 0 15px #fbb92c,0 0 55px #ff5b50;opacity:0;pointer-events:none;transform:scale(.7)}.transform-flash.show{animation:transform .9s ease-out}@keyframes transform{0%{opacity:0;transform:scale(.55)}25%{opacity:1;transform:scale(1.1)}70%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(1.15)}}
.below-arena{display:flex;align-items:center;justify-content:space-between;padding:11px 2px 0}.status-line{font-size:8px;color:#999fb8;letter-spacing:1px}.status-dot{width:6px;height:6px;margin-right:7px}.reset-link{border:0;background:transparent;color:#8990aa;font:8px var(--mono);letter-spacing:.6px;cursor:pointer}.reset-link:hover{color:#e8eaf5}.side-panel{position:relative;display:flex;flex-direction:column;padding:19px 18px 13px;border:1px solid #252a40;border-radius:5px;background:linear-gradient(145deg,#131629,#101322);min-height:100%}.panel-kicker{display:flex;justify-content:space-between;color:#a9aec3;font-size:8px}.panel-kicker span{color:#686f8c}.side-panel h2{font:800 35px/.88 var(--display);margin:24px 0 10px;letter-spacing:.2px}.side-panel h2 em{font-style:italic;color:var(--cyan)}.panel-copy{font-size:10px;line-height:1.7;color:#9da3bb;margin:0 0 20px}.move-list{border-top:1px solid #2a2f46}.move-row{height:45px;border-bottom:1px solid #252a3e;display:grid;grid-template-columns:21px 21px 1fr;column-gap:5px;align-items:center;position:relative}.keycap{height:21px;min-width:21px;display:grid;place-items:center;border:1px solid #414761;border-bottom-width:2px;border-radius:3px;background:#1a1e34;color:#e8eafa;font:10px var(--mono)}.key-wide{grid-column:span 2;width:47px}.move-name{font:700 10px var(--display);letter-spacing:.6px;margin-left:6px}.move-row small{position:absolute;right:0;bottom:7px;font:6px var(--mono);letter-spacing:.45px;color:#78809c}.panel-tip{display:flex;gap:10px;padding:12px 10px;margin-top:15px;background:#172038;border:1px solid #283955;border-radius:3px}.tip-icon{font-size:16px;color:var(--gold)}.panel-tip p{font-size:8px;line-height:1.55;color:#aab3c9;margin:0}.panel-tip b{font-size:9px;color:#f2f4ff}.side-footer{display:flex;justify-content:space-between;margin-top:auto;padding-top:15px;font-size:6px;letter-spacing:.7px;color:#69708b}.touch-controls{display:none;justify-content:space-between;gap:10px;padding:8px 0}.touch-group{display:flex;gap:7px}.touch-btn{min-width:46px;height:43px;border:1px solid #353b58;border-bottom-width:3px;border-radius:6px;background:#171b30;color:#eef0fa;font:700 13px var(--mono);touch-action:none;user-select:none;-webkit-user-select:none}.touch-btn:active,.touch-btn.pressed{background:#273454;border-color:#51e6ff}.attack-touch{color:var(--cyan)}.boost-touch{color:#ffb35e}.transform-touch{color:#ff7791;font-size:10px}.page-footer{display:flex;justify-content:space-between;border-top:1px solid #25283b;padding:12px 0 18px;font-size:7px;color:#727993;letter-spacing:1px}.page-footer i{font-style:normal;color:#4c536e;padding:0 5px}
@media(max-width:980px){body{padding:0 16px}.game-layout{grid-template-columns:minmax(0,1fr) 245px;gap:15px}.side-panel{padding:16px 13px}.side-panel h2{font-size:31px}.arena-wrap{min-height:280px}.panel-tip{margin-top:10px}}
@media(max-width:760px){body{padding:0 12px}.topbar{height:58px}.top-note{font-size:8px;letter-spacing:.7px}.sound-button{padding:7px}.sound-button span{display:none}.game-layout{display:flex;flex-direction:column;padding:13px 0 12px;gap:10px}.arena-wrap{min-height:0;border-radius:5px}.game-intro{padding:9px}.intro-eyebrow{font-size:7px}.game-intro h1{font-size:clamp(35px,10vw,62px);margin:8px 0 3px}.intro-copy{margin:5px 0 9px;font-size:9px}.select-label{font-size:7px;margin-bottom:5px}.fighter-select{width:min(360px,100%);gap:6px}.fighter-card{padding:5px 7px;gap:5px}.card-sprite{width:29px;height:32px;transform:scale(.8);transform-origin:center}.fighter-info b{font-size:13px}.fighter-info small{font-size:6px}.play-button{width:min(360px,100%);padding:8px 12px;margin-top:6px;font-size:11px}.intro-foot{margin-top:5px;font-size:6px}.battle-hud{padding:9px 9px;grid-template-columns:1fr 45px 1fr;gap:7px}.hud-name{gap:5px;margin-bottom:4px}.hud-icon{width:22px;height:22px;font-size:15px}.hud-name b{font-size:12px}.hud-name small{font-size:6px}.health-track{height:8px}.meter-row{gap:3px;font-size:5px;letter-spacing:0}.meter-track{width:clamp(22px,8vw,60px)}.meter-row b{font-size:6px}.round-clock small,.round-clock span{font-size:5px;letter-spacing:.5px}.round-clock strong{font-size:23px}.below-arena{padding-top:7px}.status-line,.reset-link{font-size:6px;letter-spacing:.5px}.side-panel{min-height:0;padding:13px 12px}.panel-kicker{font-size:7px}.side-panel h2{font-size:28px;margin:11px 0 5px}.panel-copy{font-size:9px;margin-bottom:9px}.move-list{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid #2a2f46}.move-row{height:39px;padding-right:2px}.move-row:nth-child(odd){margin-right:7px}.move-row:nth-child(even){margin-left:7px}.move-name{font-size:9px}.move-row small{font-size:5px;bottom:5px}.keycap{height:18px;min-width:18px;font-size:8px}.key-wide{width:41px}.panel-tip{margin-top:8px;padding:7px}.panel-tip p{font-size:7px}.panel-tip b{font-size:8px}.tip-icon{font-size:13px}.side-footer{display:none}.touch-controls{display:flex}.touch-btn{min-width:39px;height:38px;font-size:11px}.page-footer{font-size:6px;padding:8px 0 12px}.game-layout{padding-bottom:7px}}
@media(max-width:420px){.top-note{font-size:7px}.brand{font-size:17px}.brand-mark{width:25px;height:25px}.fighter-info small{letter-spacing:0}.fighter-card{gap:2px;padding:4px}.card-sprite{width:25px}.intro-foot{letter-spacing:.5px}.touch-btn{min-width:34px;height:36px}.move-row small{letter-spacing:0}.panel-copy{line-height:1.45}}
@media(max-height:700px) and (min-width:761px){.game-layout{padding-top:14px}.arena-wrap{min-height:0}.side-panel{padding-top:13px}.side-panel h2{margin-top:13px}.move-row{height:39px}.panel-copy{margin-bottom:13px}.panel-tip{margin-top:10px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height, FLOOR = 432;
  const $ = id => document.getElementById(id);
  const intro = $('intro'), hud = $('hud'), overlay = $('roundOverlay');
  const selectedButtons = [...document.querySelectorAll('.fighter-card')];
  const keys = Object.create(null), touchHeld = Object.create(null);
  let selected = 'sonic', running = false, ended = false, paused = false;
  let player, cpu, timeLeft = 99, lastTime = 0, roundDelay = 0, shake = 0, particles = [], rings = [], ambient = 0;
  let audioOn = true, audioCtx = null;

  const palettes = {
    sonic: {body:'#168de0', dark:'#1250b8', light:'#56cfff', skin:'#f6c19a', shoe:'#f04448', trim:'#fff7ed', eye:'#f7f8ff', pupil:'#142347', aura:'#54eaff'},
    shadow:{body:'#242635', dark:'#111522', light:'#e53355', skin:'#e8b18d', shoe:'#e52d50', trim:'#f7f4ee', eye:'#ff354e', pupil:'#171521', aura:'#ff3e67'}
  };
  // 16-bit pixel silhouettes. Each character has its own recognizable quills, streaks and shoes.
  const spriteMaps = {
    sonic:[
      '...BBBB.........','..BBBBBBB.......','.BBBBBBBBB......','BBBBBBBBBBBB....','..BBBBBBBBBBBB..','...BBBBBBBBBBBB.','....BBLLLLBBBBB.','.....BLLLLLBBBB.','......BLLLWWBBB.','......BLLLWWBBB.','.......BBWWBBBB.','.......SSSSBBBB.','......SSSSSSBB..','.....SSSSSSSS...','.....DDSSDD.....','....DD.DD.DD....','...RRR..RRRR....','..WWWW..WWWW....','..WWWW..WWWW....'
    ],
    shadow:[
      'RR..BBBB.........','RR.BBBBBBB.......','.RBBBBBBBB.......','BBBBBBBBBBBB.....','..BBBBBBBBBBBB...','...BBBBBBBBBBBB..','....BBLLLLBBBBB..','.....BLLLLLBBBB..','......BLLLWWBBB..','......BLLLWWBBB..','.......BBWWBBBB..','.......SSSSBBBB..','......SSSSSSBB...','.....SSSSSSSS....','.....DDSSDD......','....DD.DD.DD.....','...RRR..RRRR.....','..WWWW..WWWW.....','..WWWW..WWWW.....'
    ]
  };
  function beep(freq=360,duration=.06,type='square',volume=.035){
    if(!audioOn)return;
    try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch(_){ }
  }
  function fighter(kind,x,isCpu=false){return {kind,x,y:FLOOR,vx:0,vy:0,face:isCpu?-1:1,health:100,meter:kind==='shadow'?10:0,attack:0,attackKind:'spin',attackHit:false,boostCooldown:0,stun:0,transformed:0,walk:0,flash:0,block:false,isCpu};}
  function startGame(){
    selectedButtons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.fighter===selected)));
    player=fighter(selected,246,false);cpu=fighter(selected==='sonic'?'shadow':'sonic',714,true);
    running=true;ended=false;paused=false;timeLeft=99;particles=[];rings=[];shake=0;roundDelay=1.35;
    intro.classList.add('hidden');hud.classList.add('active');overlay.classList.remove('show');$('statusText').textContent='FIGHT! LAND HITS TO CHARGE YOUR CHAOS METER';
    $('playerName').textContent=selected.toUpperCase();$('cpuName').textContent=cpu.kind.toUpperCase();
    $('playerIcon').textContent=selected==='sonic'?'S':'S';$('cpuIcon').textContent='S';$('cpuIcon').classList.toggle('shadow-icon',cpu.kind==='shadow');$('playerIcon').classList.toggle('shadow-icon',selected==='shadow');
    syncHud();
  }
  selectedButtons.forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.fighter;selectedButtons.forEach(c=>{c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',String(c===b))});beep(540,.04)}));
  $('playButton').addEventListener('click',()=>{startGame();beep(250,.12,'sawtooth')});
  $('rematchButton').addEventListener('click',()=>{startGame();beep(260,.1,'sawtooth')});
  $('resetButton').addEventListener('click',()=>{running=false;ended=false;overlay.classList.remove('show');hud.classList.remove('active');intro.classList.remove('hidden');$('statusText').textContent='PICK YOUR SIDE AND GET READY';});
  $('soundButton').addEventListener('click',()=>{audioOn=!audioOn;$('soundButton').innerHTML=audioOn?'♫ <span>SOUND ON</span>':'♫ <span>SOUND OFF</span>';if(audioOn)beep(520,.05)});
  function setAction(action,down){touchHeld[action]=down;const button=document.querySelector(`[data-action="${action}"]`);if(button)button.classList.toggle('pressed',down);if(down&&action==='attack')doAttack(player,'spin');if(down&&action==='boost')doAttack(player,'boost');if(down&&action==='transform')transform(player);if(down&&action==='jump'&&running&&!ended&&player.y>=FLOOR-1){player.vy=-570;beep(420,.04)}}
  document.querySelectorAll('.touch-btn').forEach(button=>{
    const action=button.dataset.action;
    button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);if(['left','right'].includes(action))setAction(action,true);else setAction(action,true)});
    const release=e=>{if(['left','right'].includes(action))setAction(action,false);else setAction(action,false)};
    button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release);
  });
  window.addEventListener('keydown',e=>{
    const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','j','k','l','a','d','w'].includes(k))e.preventDefault();keys[k]=true;
    if(e.repeat||!running||ended)return;
    if(k==='j'||k==='z')doAttack(player,'spin');if(k==='k'||k==='x')doAttack(player,'boost');if(k==='l'||k==='c')transform(player);
    if((k==='arrowup'||k==='w'||k===' ')&&player.y>=FLOOR-1){player.vy=-570;beep(420,.04)}
    if(k==='escape'||k==='p'){paused=!paused;$('statusText').textContent=paused?'PAUSED · PRESS P TO RESUME':'FIGHT! LAND HITS TO CHARGE YOUR CHAOS METER'}
  });
  window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
  window.addEventListener('blur',()=>{for(const k in keys)keys[k]=false;for(const k in touchHeld)touchHeld[k]=false});

  function doAttack(f,kind){if(!running||ended||paused||roundDelay>0||f.stun>0)return;if(kind==='boost'&&f.boostCooldown>0)return;if(f.attack>0)return;
    f.attack=kind==='boost'?.32:.25;f.attackKind=kind;f.attackHit=false;
    if(kind==='boost'){f.boostCooldown=1.05;f.vx=f.face*(f.transformed?730:590);f.vy=Math.min(f.vy,0);beep(170,.13,'sawtooth',.045)}else beep(f.kind==='sonic'?520:330,.055,'square',.025);
  }
  function transform(f){if(!running||ended||paused||roundDelay>0||f.transformed>0||f.meter<100)return;f.meter=0;f.transformed=8;f.health=Math.min(100,f.health+7);burst(f.x,f.y-43,palettes[f.kind].aura,26);$('transformFlash').classList.remove('show');void $('transformFlash').offsetWidth;$('transformFlash').classList.add('show');$('statusText').textContent=`${f.kind.toUpperCase()} UNLEASHED CHAOS CONTROL`;beep(105,.26,'sawtooth',.06);setTimeout(()=>beep(710,.26,'triangle',.04),90);}

  function bg(){
    const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#172347');sky.addColorStop(.52,'#392c63');sky.addColorStop(1,'#14152c');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    // distant moon and pixel stars
