function updateFighter(f,other,dt){
  f.attack=Math.max(0,f.attack-dt);f.boostCooldown=Math.max(0,f.boostCooldown-dt);f.stun=Math.max(0,f.stun-dt);f.flash=Math.max(0,f.flash-dt);f.transformed=Math.max(0,f.transformed-dt);
