  timeLeft=Math.max(0,timeLeft-dt);player.meter=Math.min(100,player.meter+dt*.75);cpu.meter=Math.min(100,cpu.meter+dt*.7);
  if(cpu.meter>=100&&cpu.transformed<=0&&Math.random()<dt*.7)transform(cpu);
